const app=document.querySelector('#app');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n||0).toLocaleString(),short=s=>s?escape(s.slice(0,7)+'…'+s.slice(-5)):'—';
const chainNames={Base:'Base',BSC:'BNB Chain',opBNB:'opBNB',Greenfield:'BNB Greenfield',Solana:'Solana',Ethereum:'Ethereum',Polygon:'Polygon',Arbitrum:'Arbitrum',Optimism:'Optimism',Avalanche:'Avalanche',XRP:'XRP Ledger'};
const href=(params={})=>'/ai-agents-apps/?'+new URLSearchParams(params);
const badges=ns=>ns.map(n=>`<span class="badge ${escape(n.toLowerCase())}"><span>◈</span>${escape(chainNames[n]||n)}</span>`).join('');
const dateTime=t=>t?new Date(t).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}):'Unavailable';
const date=t=>t?new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Unavailable';
const logo=p=>`<img src="${escape((p.logo||'/ai-agents-apps/fallback.svg').replace(/^\/hub\/logos\//,'/ai-agents-apps/logos/').replace(/^\/logos\//,'/ai-agents-apps/logos/'))}" alt="" data-fallback>`;
let state={q:'',chain:'All',category:'All',sort:'curated',page:1,layout:'grid'},generation=0;
let saved=()=>{try{return JSON.parse(localStorage.getItem('x402-local-submissions')||'[]')}catch{return[]}};
let refreshDetail;let snapshotPromise;const detailPromises=new Map();
async function api(url){
 const s=await (snapshotPromise ||= Promise.all([fetch('/ai-agents-apps/snapshot-summary-v3.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Activity data is temporarily unavailable');return r.json()}),fetch('/ai-agents-apps/reviewed-projects.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Reviewed listings are temporarily unavailable');return r.json()})]).then(async([s,review])=>{await Promise.all(review.projects.map(async p=>{if(p.sampleOnly&&!p.activityConnected)return;try{const key=p.activityKey||({'tanod.dev':'tanod','horizonpulse.dev':'horizon','vextorium.com':'vextorium'}[p.id]),r=await fetch((p.sampleOnly?'/new-listings/community-activity.php?project=':'/new-listings/activity.php?project=')+key,{cache:'no-store'});if(!r.ok)return;const d=await r.json();if(!Number.isFinite(d.transactions))return;p.metrics={transactions:d.transactions,wallets:d.wallets,latest:(d.rows?.[0]?.timestamp||0)*1000,attributed:true};p.metricLabel=(p.activityShared?'Shared wallet transfers · 30d':'USDC receipts · 30d')+(d.partial?' · partial':'');p.activityPartial=d.partial;p.activitySource='Recipient USDC index';p.analyticsNote=d.coverage;}catch{}}));s.reviewed=review.projects;const ids=new Set(s.projects.map(p=>p.id));for(const p of s.reviewed){if(ids.has(p.id))continue;s.projects.push(p);for(const n of p.networks)if(s.chains[n])s.chains[n].push(p)}return s}));
 const u=new URL(url,location.origin),p=u.searchParams;
 if(u.pathname.endsWith('/networks'))return s.networks;
 if(u.pathname.endsWith('/project')){const reviewed=s.reviewed.find(x=>x.id===p.get('id'));if(reviewed)return {reviewed:true,project:reviewed};const key=[p.get('id'),p.get('chain')||'All',p.get('days')||30].join('|'),file=s.detailFiles[key];if(!file)throw Error('Project data is unavailable');if(!detailPromises.has(key))detailPromises.set(key,fetch('/ai-agents-apps/details-fast/'+file,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Project details are temporarily unavailable');return r.json()}));const d=await detailPromises.get(key);if(!d)throw Error('Project data is unavailable');return d;}
 if(u.pathname.endsWith('/projects')){
  const chain=p.get('chain')||'All',category=p.get('category')||'All',q=(p.get('q')||'').toLowerCase(),sort=p.get('sort');
  let a=[...(s.chains[chain]||s.projects)].filter(x=>(chain==='All'||x.networks.includes(chain))&&(category==='All'||x.category===category)&&[x.name,x.description,x.id].join(' ').toLowerCase().includes(q));
  a.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='users'?(b.metrics.wallets||0)-(a.metrics.wallets||0):sort==='activity'?b.metrics.transactions-a.metrics.transactions:a.order-b.order);
  const connected=a.filter(x=>x.metrics.attributed&&x.metrics.transactions>0),waiting=a.filter(x=>!x.metrics.attributed||x.metrics.transactions<=0),pages=[];
  for(const [kind,group]of[['activity',connected],['awaiting',waiting]])for(let i=0;i<group.length;i+=9)pages.push({kind,items:group.slice(i,i+9)});
  const page=Math.max(1,Number(p.get('page'))||1),selected=pages[page-1];return{items:selected?.items||[],total:a.length,pages:Math.max(1,pages.length),page,pageType:selected?.kind||'activity',indexedThrough:s.indexedThrough};
 }
 throw Error('Use the public GitHub registry to submit or update a listing.');
}
const error=e=>`<div class="error" role="alert">${escape(e.message)} <button class="chip" data-retry>Try again</button></div>`;
function wire(){document.querySelectorAll('[data-fallback]').forEach(img=>{img.onerror=()=>{img.onerror=null;img.src='/ai-agents-apps/fallback.svg'}});document.querySelector('[data-retry]')?.addEventListener('click',render)}
async function render(){let params=new URLSearchParams(location.search);const view=params.get('view');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(view==='mine'?'mine':'browse')));if(view==='monetize')return monetize();if(view==='submit')return submit();if(view==='mine')return mine();if(params.has('project'))return detail(params.get('project'));browse();}
function browse(){app.innerHTML=`<div class="wrap"><section class="hero"><div><span class="eyebrow">BUILT FOR A MULTICHAIN WORLD</span><h1>The next generation<br>of <em>agents & apps.</em></h1><p class="intro">Discover AI agents, explore onchain apps, and follow the activity behind them. One directory. Every chain.</p><div class="herostrip"><span><b>AI agents</b> that do more</span><span><b>Apps</b> built onchain</span><span><b>x402</b> powered APIs</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="core">Ⅹ</div><div class="node one"><i class="dot"></i>Base</div><div class="node two"><i class="dot purple"></i>AI agents</div><div class="node three"><i class="dot gold"></i>BNB Chain</div><div class="node four"><i class="dot green"></i>Solana</div></div></section><section id="network-cards" aria-label="Network activity"><p class="muted">Loading network activity…</p></section><div class="toolbar"><label class="search"><span>⌕</span><input id="search" type="search" aria-label="Search agents and apps" placeholder="Search agents, apps, APIs…" value="${escape(state.q)}"></label><select id="category" aria-label="Filter by category">${['All','AI agents','Apps','APIs & data','Payment infrastructure','Developer tools'].map(x=>`<option ${x===state.category?'selected':''} value="${x}">${x==='All'?'All categories':x}</option>`).join('')}</select><select id="sort" aria-label="Sort projects"><option value="curated">Curated selection</option><option value="activity">Most indexed transactions</option><option value="users">Most active wallets</option><option value="name">Name A–Z</option></select></div><div class="chainbar" role="group" aria-label="Filter by blockchain">${['All',...Object.keys(chainNames)].map(x=>`<button class="chip ${x===state.chain?'active':''}" data-chain="${x}">${x==='All'?'All chains':chainNames[x]}</button>`).join('')}</div><section><div class="resultsline"><h2>Agents, apps & reviewed APIs <span class="count" id="total">…</span></h2><div class="view-toggle" role="group" aria-label="Display layout"><button data-layout="grid" class="${state.layout==='grid'?'selected':''}" aria-label="Grid view">▦</button><button data-layout="list" class="${state.layout==='list'?'selected':''}" aria-label="List view">☰</button></div></div><div id="results" aria-live="polite"><p class="empty">Loading project activity…</p></div></section><section class="monetize-teaser"><div><span class="eyebrow">FOR THE NEXT STAGE</span><h2>Build an audience. Build a business.</h2><p>Discover growth and monetization opportunities for your agent or app.</p></div><a class="button" href="${href({view:'monetize'})}">Grow & monetize ↗</a></section><aside class="cta"><div><span class="eyebrow">FOR BUILDERS</span><h2 style="margin-top:12px">Your next users are looking for you.</h2><p>List your agent or app. Connect your chains. Make your activity discoverable.</p></div><a href="${href({view:'submit'})}" class="button primary">List your project ↗</a></aside></div>`;
document.querySelector('#sort').value=state.sort;let timer;document.querySelector('#search').oninput=e=>{state.q=e.target.value;state.page=1;clearTimeout(timer);timer=setTimeout(loadProjects,220)};for(const k of ['category','sort'])document.querySelector('#'+k).onchange=e=>{state[k]=e.target.value;state.page=1;loadProjects()};document.querySelectorAll('[data-chain]').forEach(b=>b.onclick=()=>{state.chain=b.dataset.chain;state.page=1;document.querySelectorAll('[data-chain]').forEach(c=>c.classList.toggle('active',c===b));loadProjects()});document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{state.layout=b.dataset.layout;document.querySelectorAll('[data-layout]').forEach(c=>c.classList.toggle('selected',c===b));document.querySelector('.cards')?.classList.toggle('list',state.layout==='list')});loadProjects();loadNetworks();}
async function loadProjects(){const id=++generation;const target=document.querySelector('#results');try{const d=await api('/api/hub/projects?'+new URLSearchParams(state));if(id!==generation||!document.contains(target))return;document.querySelector('#total').textContent=num(d.total);target.innerHTML=`<div class="directory-status"><div><strong>${d.pageType==='awaiting'?'Awaiting activity data':'Transaction activity connected'}</strong><p>${d.pageType==='awaiting'?'These profiles need a verified activity feed. A missing count does not mean zero usage.':'Project activity from connected data sources. Each profile shows its coverage and check date.'}</p></div><div class="page-buttons">${Array.from({length:d.pages},(_,i)=>`<button data-page="${i+1}" class="${i+1===d.page?'active':''}" aria-label="Page ${i+1}" ${i+1===d.page?'aria-current="page"':''}>${i+1}</button>`).join('')}</div></div><div class="cards ${state.layout==='list'?'list':''}">${d.items.map(p=>`<a class="project" href="${href({project:p.id})}"><div class="cardbody"><div class="projecttop">${logo(p)}<div><h3>${escape(p.name)}</h3><small>${escape(p.category)}${p.approved?' · Approved listing':''}</small></div><span class="arrow">↗</span></div><p class="desc">${escape(p.description)}</p><div class="badges">${badges(p.networks)}</div><div class="cardstats"><div><small>${escape(p.metricLabel||'Transactions · 30d')}</small><strong>${p.metrics.attributed?num(p.metrics.transactions):'—'}</strong></div><div><small>${p.approved?'Sender wallets':'Active wallets'}</small><strong>${p.metrics.attributed&&p.metrics.wallets!==null?num(p.metrics.wallets):'—'}</strong></div><div><small>Networks</small><strong style="color:#6683bd">${p.networks.length}</strong></div></div></div><div class="cardfoot"><span class="statusdot ${p.metrics.attributed&&p.metrics.transactions>0?'connected':'waiting'}">${p.metrics.attributed&&p.metrics.transactions>0?(p.sourceStatus==='delayed'?'◐ Update delayed':p.activityPartial||p.sourceStatus==='partial'?'◐ Partial index':'● Data connected'):'◌ Awaiting data'}</span><span>${p.metrics.latest?(p.activitySource?'Activity through ':'Last payment ')+date(p.metrics.latest):(p.analyticsNote?'Project activity feed needed':'Analytics not connected')}</span></div></a>`).join('')}</div>${!d.items.length?'<div class="empty">No indexed projects match these filters.<br><a class="button small" href="'+href({view:'submit'})+'">Be the first to list here ↗</a></div>':''}<div class="pager"><span>Page ${d.page} of ${d.pages} · ${num(d.total)} projects</span><div><button id="prev" ${d.page<=1?'disabled':''}>← Previous</button><button id="next" ${d.page>=d.pages?'disabled':''}>Next →</button></div></div><p class="data-note">${escape(d.source)} Latest indexed receipt: ${date(d.indexedThrough)}. Source-reported contract activity and indexed payments have different scopes. Open a profile for its source and coverage. Missing coverage is shown as unavailable. Curated ecosystem profiles and approved community applications. Ecosystem inclusion is not a partnership or a claim that every app supports x402.</p>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.page);loadProjects()});document.querySelector('#prev').onclick=()=>{state.page--;loadProjects()};document.querySelector('#next').onclick=()=>{state.page++;loadProjects()};wire();}catch(e){if(document.contains(target))target.innerHTML=error(e);wire()}}
async function detail(id){app.innerHTML='<div class="wrap"><a class="back" href="/ai-agents-apps/">← Back to discovery</a><div id="detail"><p class="empty">Loading project activity…</p></div></div>';let chain='All',days=30;async function load(){try{const d=await api('/api/hub/project?'+new URLSearchParams({id,chain,days}));const p=d.project;if(d.reviewed){reviewedDetail(p);return}document.querySelector('#detail').innerHTML=`<div class="detailhero">${logo(p)}<div><span class="eyebrow">${escape(p.category)}</span><h1 style="margin-top:10px">${escape(p.name)}</h1><p>${escape(p.description)}</p></div><a class="button small" href="${escape(p.website)}" target="_blank" rel="noopener">Open app ↗</a></div><div class="badges">${badges(p.networks)}<span class="badge">◇ Curated profile</span></div><div class="tabs"><button class="active">Activity</button><a href="#resources">API resources</a><a href="${href({view:'submit'})}">List another project ↗</a></div><div class="resultsline"><div class="chainbar">${['All',...p.networks].map(n=>`<button data-chain="${escape(n)}" class="chip ${n===chain?'active':''}">${escape(chainNames[n]||n)}</button>`).join('')}</div><select id="days" class="chip" aria-label="Activity period"><option value="7" ${days===7?'selected':''}>Last 7 days</option><option value="30" ${days===30?'selected':''}>Last 30 days</option></select></div>${d.facilitatorStats?`<section class="panel"><h2>Published facilitator activity · ${days} days</h2><div class="stats"><div class="stat"><p>PAYMENT TRANSACTIONS</p><strong>${num(d.facilitatorStats.transactions)}</strong></div><div class="stat"><p>UNIQUE BUYERS</p><strong>${num(d.facilitatorStats.wallets)}</strong></div></div><p class="muted">${escape(d.facilitatorStats.scope)}</p><p><a class="hs-link" href="${escape(d.facilitatorStats.sourceUrl)}" target="_blank" rel="noopener">Data reference ↗</a> · Checked ${dateTime(d.facilitatorStats.checkedAt)}</p><p class="muted">The records and chart below are a separate, smaller retained index.</p></section>`:''}${d.published?`<section class="panel"><h2>Published activity · separate datasets</h2><p class="muted">These counts measure different activity and must not be added together.</p><div class="stats">${d.published.periods?.[days]&&chain!=='BSC'?`<div class="stat"><p>BASE API PAYMENTS · ${days} DAYS</p><strong>${num(d.published.periods[days].transactions)}</strong><small>${num(d.published.periods[days].wallets)} unique buyers · reported payment coverage</small><p><a class="hs-link" href="${escape(d.published.periods[days].sourceUrl)}" target="_blank" rel="noopener">View source ↗</a></p><small>${escape(d.published.periods[days].scope)} Checked ${dateTime(d.published.periods[days].checkedAt)}.</small></div>`:''}${d.published.bnb&&chain!=='Base'?`<div class="stat"><p>BNB SIGNER · LIFETIME OUTGOING</p><strong>${num(d.published.bnb.outgoingTransactions)}</strong><small>Onchain account nonce · not payment total</small><p><a class="hs-link" href="${escape(d.published.bnb.sourceUrl)}" target="_blank" rel="noopener">View address ↗</a></p><small>${escape(d.published.bnb.scope)} Checked ${dateTime(d.published.bnb.checkedAt)}.</small></div>`:''}</div>${chain!=='BSC'&&d.published.periods?.[days]?.history?.length?`<h3>Base API payment activity · source buckets</h3>${chart(d.published.periods[days].history,'source buckets')}`:''}</section>`:''}<div class="stats"><div class="stat"><p>${d.sourceReported?'CONTRACT TRANSACTIONS':'INDEXED SUBSET · TRANSACTIONS'}</p><strong>${d.attributed?num(d.transactions):'—'}</strong><small>${d.sourceReported?'Reported by '+escape(d.source):'Distinct chain + transaction'}</small></div><div class="stat"><p>ACTIVE WALLETS</p><strong>${d.attributed&&d.activeWallets!==null?num(d.activeWallets):'—'}</strong><small>${d.sourceReported?'Provider period users · not web visitors':'Wallets, not individual users'}</small></div><div class="stat"><p>NETWORKS</p><strong>${p.networks.length}</strong><small>Project-reported capabilities</small></div><div class="stat"><p>API RESOURCES</p><strong>${p.resources>0?num(p.resources):'—'}</strong><small>From the indexed catalogue</small></div></div><section class="panel"><div class="panelhead"><h2>${d.sourceReported?'Contract activity':(d.published||d.facilitatorStats)?'Retained index subset payment activity':'Payment activity'}</h2><small class="muted">Daily transactions · UTC</small></div>${d.attributed?chart(d.history):'<p class="empty">Connect and verify a receiving wallet to enable attributable analytics.</p>'}</section>${d.sourceReported?`<section class="panel"><h2>Activity source</h2><p>${escape(d.coverage)}</p><p><a class="hs-link" href="${escape(d.sourceUrl)}" target="_blank" rel="noopener">${escape(d.source)} ↗</a> · Checked ${dateTime(d.checkedAt)} · Data through ${date(d.indexedThrough)}</p><p class="muted">Transaction hashes and token volume are not supplied by this aggregate source. They are not inferred from activity totals.</p></section>`:''}<section class="panel"><div class="panelhead"><h2>Recent indexed transactions</h2><small class="muted">Up to 50 latest records</small></div>${d.rows.length?`<div class="tablewrap"><table><thead><tr><th>Transaction</th><th>Chain</th><th>Payer</th><th>Token amount</th><th>Date</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.explorer?`<a href="${escape(r.explorer)}" target="_blank" rel="noopener">${short(r.hash)} ↗</a>`:short(r.hash)}</td><td>${escape(chainNames[r.network]||r.network)}</td><td>${short(r.payer)}</td><td>${units(r.amount,r.decimals)}</td><td>${dateTime(r.timestamp)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${d.sourceReported?'Daily totals are connected. Individual transaction hashes require a separate explorer or RPC index.':'No indexed transactions for this selection.<br>This does not mean the project has no activity outside our coverage.'}</div>`}</section><section class="panel" id="resources"><h2>Project sources & API resources</h2>${p.documentation?`<p><a class="hs-link" href="${escape(p.documentation)}" target="_blank" rel="noopener">Official documentation ↗</a></p>`:''}${p.analyticsNote?`<p class="muted">${escape(p.analyticsNote)}</p>`:''}${p.id==='payai.network'?'<p class="muted">The catalogue below contains merchant APIs discovered through PayAI, not APIs owned by PayAI.</p>':''}<p class="muted" style="font-size:12px">${escape(p.selection||'')} <a class="hs-link" href="${escape(p.reference||p.website)}" target="_blank" rel="noopener">View source ↗</a></p>${p.services.length?`<div class="tablewrap"><table><thead><tr><th>Method</th><th>Resource</th></tr></thead><tbody>${p.services.map(s=>`<tr><td>${escape(s.method)}</td><td>${escape(s.url)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No public API catalogue connected. This profile does not imply x402 support.</p>'}</section><p class="data-note">${escape(d.coverage)} ${d.sourceReported?'Provider data through':'Latest indexed receipt'}: ${date(d.indexedThrough)}. ${d.sourceReported?'Dates show the provider’s actual coverage.':'These metrics are from the retained local index, not a live chain-wide data feed.'} Web visits and offchain users are not collected.</p>`;document.querySelectorAll('[data-chain]').forEach(b=>b.onclick=()=>{chain=b.dataset.chain;load()});document.querySelector('#days').onchange=e=>{days=Number(e.target.value);load()};wire();}catch(e){document.querySelector('#detail').innerHTML=error(e);wire()}}refreshDetail=load;load()}
function units(s,dec){let n=String(s).padStart(dec+1,'0');return escape(dec?n.slice(0,-dec)+(n.slice(-dec).replace(/0+$/,'')?'.'+n.slice(-dec).replace(/0+$/,''):''):n)}
function chart(h,periodUnit='days'){let max=Math.max(1,...h.map(p=>p.count));return `<svg class="chart" viewBox="0 0 960 210" role="img" aria-label="Transaction activity, ${h.length} ${periodUnit}"><title>Transaction activity</title>${[0,1,2,3].map(i=>`<line x1="25" y1="${20+i*48}" x2="950" y2="${20+i*48}" stroke="#edf0f7"/><text x="0" y="${24+i*48}">${num(Math.round(max*(1-i/3)))}</text>`).join('')}${h.map((p,i)=>{let w=910/h.length,x=35+i*w,height=p.count/max*140;return `<rect x="${x}" y="${165-height}" width="${Math.max(3,w-5)}" height="${height||1}" rx="3" fill="${p.count?'#4c78f5':'#e5eafa'}"><title>${p.date}: ${num(p.count)} transactions</title></rect>`}).join('')}<text x="35" y="198">${date(Date.parse(h[0].date))}</text><text x="820" y="198">${date(Date.parse(h.at(-1).date))}</text></svg>`}
function listingLinks(){try{return JSON.parse(localStorage.getItem('x402-public-listing-links')||'[]')}catch{return[]}}
function submit(){
 app.innerHTML=`<div class="wrap"><a class="back" href="/ai-agents-apps/">← Back to discovery</a><div class="form-layout"><aside class="form-side"><span class="eyebrow">BUILDER ONBOARDING</span><h3>A home for your project.</h3><ol><li>Tell us what you are building</li><li>Prepare your public proposal</li><li>Create a pull request on GitHub</li><li>Our team reviews your evidence</li></ol><p>Your GitHub pull request is the official application. Submission does not automatically approve or publish a project.</p></aside><section id="form-area"><span class="eyebrow">BUILT SOMETHING?</span><h1 style="margin-top:18px">Make it discoverable.</h1><p class="intro">List your AI agent, app, paid API or payment infrastructure across the chains you support.</p><form id="listing-form"><div id="form-error" role="alert"></div><div class="form-grid"><label class="field">Project name *<input name="name" required minlength="2" maxlength="80"></label><label class="field">Category *<select name="category" required>${['AI agents','Apps','APIs & data','Payment infrastructure','Developer tools'].map(n=>`<option>${n}</option>`).join('')}</select></label></div><label class="field">What does it do? *<textarea name="description" required minlength="30" maxlength="1200" rows="4"></textarea></label><div class="form-grid">${[['website','Official website *',true],['docs','Documentation URL',false],['logo','Logo URL',false],['github','Public repository URL',false],['support','Public support URL',false],['endpoint','Public API endpoint',false]].map(([name,label,required])=>`<label class="field">${label}<input name="${name}" type="url" ${required?'required':''} maxlength="300" placeholder="https://"></label>`).join('')}</div><label class="field">Networks *</label><div class="chainbar">${Object.entries(chainNames).map(([id,label])=>`<label class="check"><input type="checkbox" name="networks" value="${id}">${label}</label>`).join('')}</div><label class="field">Public payment or activity evidence<textarea name="evidence" rows="4" maxlength="3000" placeholder="Public receiving addresses, facilitator used, payment scheme/version, token contract and decimals, and a successful payment link for each applicable network. Write Not applicable if your app does not accept payments."></textarea></label><label class="field">Growth interests</label><div class="chainbar"><label class="check"><input type="checkbox" name="monetization" value="Paid agent/API usage">Paid agent/API usage</label><label class="check"><input type="checkbox" name="monetization" value="Sponsored promotion">Sponsored promotion</label></div><p class="help">Monetization and sponsored promotion are planned services. No payment is collected here.</p><section class="github-step"><span class="eyebrow">PUBLIC GITHUB REVIEW</span><h2>Send your project for review.</h2><p>Prepare the proposal below, complete it on GitHub and click Create pull request. A GitHub account is required. Do not include passwords, private contact details, API keys or payment signatures.</p><a class="button small" id="prepare-proposal" href="https://github.com/X402blockchains/x402-registry#three-easy-steps" target="_blank" rel="noopener">Prepare proposal on GitHub ↗</a><details><summary>Review your public proposal</summary><pre id="proposal-preview"></pre></details><label class="field">Your GitHub pull-request link *<input name="pullRequest" type="url" required maxlength="300" placeholder="https://github.com/X402blockchains/x402-registry/pull/123"></label><p class="help">Already submitted? Save your pull-request link below to find it again in this browser. Saving a link does not create a GitHub application or verify the pull request.</p></section><label class="check" style="margin:20px 0"><input type="checkbox" required>I represent this project and the public information is accurate.</label><button class="button primary" type="submit">Save my application link ↗</button></form></section></div></div>`;
 const form=document.querySelector('#listing-form');
 function prepare(){const f=new FormData(form),name=String(f.get('name')||'Your project'),networks=f.getAll('networks');const text=['# '+name,'','## Basic details','- Project name: '+name,'- Description: '+(f.get('description')||''),'- Type: '+f.get('category'),'- Official website: '+(f.get('website')||''),'- Logo URL: '+(f.get('logo')||''),'- Documentation: '+(f.get('docs')||''),'- Public repository: '+(f.get('github')||''),'- Public support: '+(f.get('support')||''),'','## Networks and ownership','- Networks: '+networks.map(n=>chainNames[n]||n).join(', '),'- Proof of project ownership: please add an official public reference','','## Payments and activity','Provide the paid endpoint and method, facilitator used, scheme/version, asset contract/mint and decimals, receiving wallets and successful payment link for each supported network. Write Not applicable if no payments are accepted.',String(f.get('evidence')||''),'','## Growth interests (planned services)',f.getAll('monetization').join(', ')||'Not selected','','No private credentials or signed payment authorizations.'].join('\n');document.querySelector('#proposal-preview').textContent=text;const slug=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'your-project';document.querySelector('#prepare-proposal').href='https://github.com/X402blockchains/x402-registry/new/main?'+new URLSearchParams({filename:'proposals/'+slug+'.md',value:text});}
 form.addEventListener('input',prepare);prepare();
 form.onsubmit=e=>{e.preventDefault();const f=new FormData(form);try{if(!f.getAll('networks').length)throw Error('Choose at least one network.');const u=new URL(f.get('pullRequest'));if(u.protocol!=='https:'||u.hostname!=='github.com'||u.username||u.password||u.port||!/^\/X402blockchains\/x402-registry\/pull\/[1-9]\d*\/?$/i.test(u.pathname))throw Error('Use a pull-request link from X402blockchains/x402-registry.');u.search='';u.hash='';const entry={name:String(f.get('name')),url:u.href,createdAt:Date.now()},entries=listingLinks().filter(x=>x.url!==entry.url);entries.push(entry);localStorage.setItem('x402-public-listing-links',JSON.stringify(entries));document.querySelector('#form-area').innerHTML=`<div class="success"><span class="eyebrow">APPLICATION LINK SAVED</span><h1 style="font-size:32px">Keep building.</h1><p>Your link is saved in this browser. The GitHub pull request is the official submission; our team must verify its existence, ownership and evidence before approval.</p><a class="button primary" href="${escape(entry.url)}" target="_blank" rel="noopener">View pull request ↗</a><p><a href="${href({view:'mine'})}">My application links →</a></p></div>`;}catch(err){document.querySelector('#form-error').innerHTML='<p class="error">'+escape(err.message)+'</p>';}};
}
function mine(){const entries=listingLinks();app.innerHTML=`<div class="wrap"><a class="back" href="/ai-agents-apps/">← Back to discovery</a><span class="eyebrow">YOUR BUILDER WORKSPACE</span><h1 style="font-size:40px">My application links</h1><p class="intro">Links saved in this browser. Open GitHub to see the latest review status. A saved link is not an approval or a verified application.</p><div style="margin-top:30px">${entries.length?entries.map(x=>`<article class="panel"><h2>${escape(x.name)}</h2><p class="muted">Saved ${date(x.createdAt)}</p><a class="button small" href="${escape(x.url)}" target="_blank" rel="noopener">View GitHub review ↗</a></article>`).join(''):'<div class="empty">No application links saved yet.<br><a class="button small" href="'+href({view:'submit'})+'">List your project ↗</a></div>'}</div></div>`;}
function monetize(){app.innerHTML=`<div class="wrap"><a class="back" href="/ai-agents-apps/">← Back to discovery</a><section class="hero"><div><span class="eyebrow">GROW & MONETIZE · PLANNED</span><h1>Turn your agent<br>into a <em>business.</em></h1><p class="intro">Bring your app to the right audience, then build a revenue model around the value it creates.</p><a class="button primary" href="${href({view:'submit'})}">Apply for listing & register interest ↗</a></div><div class="panel"><h2>Transparent growth</h2><p class="intro" style="font-size:14px">Activity rankings remain based on measured usage. Paid promotion will be clearly labelled Sponsored and will not buy a verified badge or change organic rankings.</p></div></section><div class="cards monetization-cards"><article class="panel"><span class="eyebrow">01 · PAID USAGE</span><h2>Earn from every useful action.</h2><p>Planned support for per-request APIs and agent services using compatible x402 payments. Creators choose pricing; supported chain and asset availability will be shown before integration.</p></article><article class="panel"><span class="eyebrow">02 · PROMOTION</span><h2>Reach your next users.</h2><p>Planned sponsored discovery placements and campaign opportunities for qualifying projects. Eligibility will consider documented activity, product quality and review status.</p></article><article class="panel"><span class="eyebrow">03 · INSIGHTS</span><h2>Understand what’s working.</h2><p>Project pages show attributable indexed activity when data is connected. Wallets are not people, and analytics will never promise user growth or revenue.</p></article></div><p class="data-note">These are planned services. Pricing, revenue share, campaign packages, eligibility and payment processing are not launched. Register interest in the listing form; no purchase, payout or revenue guarantee is made.</p></div>`;}
render();

async function loadNetworks(){const target=document.querySelector('#network-cards');if(!target)return;try{const d=await api('/api/hub/networks');if(!document.contains(target))return;target.innerHTML=`<div class="network-heading"><div><span class="eyebrow">EXPLORE BY NETWORK</span><h2>Base, Solana & BNB Chain</h2></div><span class="muted">x402 payments · last 30 days</span></div><div class="network-grid">${['Base','Solana','BSC'].map(network=>{const name=network==='BSC'?'BNB Chain':network;const n=d.items.find(x=>x.network===network);return `<article class="network-card ${name.toLowerCase()}"><div class="network-title"><img src="/ai-agents-apps/logos/${network==='BSC'?'bnb':network.toLowerCase()}.svg" alt=""><div><h3>${name}</h3><small>${n?.partial?'Partial payment index':'Reported payment coverage'}</small></div><a href="${network==='Base'?'https://www.base.org/':network==='BSC'?'https://www.bnbchain.org/':'https://solana.com/'}" target="_blank" rel="noopener">↗</a></div><div class="network-stats"><div><small>Payment transactions</small><strong>${n?num(n.transactions):'—'}</strong></div><div><small>${network==='BSC'?'Reported buyers':'Unique buyers'}</small><strong>${n?num(n.wallets):'—'}</strong></div><div><small>${network==='BSC'?'Reported sellers':'Paid sellers'}</small><strong>${n?num(n.sellers):'—'}</strong></div></div><div class="network-bottom"><span>${n?'Data through '+date(Date.parse(n.latest)):'Source unavailable'}</span><button data-network-filter="${network}">Explore ${name} projects →</button></div></article>`}).join('')}</div><p class="network-note">Reported x402 payment activity over the last 30 days. Coverage and address-count definitions differ between networks; these are not complete blockchain totals or individual user counts.</p>`;target.querySelectorAll('[data-network-filter]').forEach(b=>b.onclick=()=>{state.chain=b.dataset.networkFilter;state.page=1;document.querySelectorAll('[data-chain]').forEach(c=>c.classList.toggle('active',c.dataset.chain===state.chain));loadProjects();document.querySelector('#results')?.scrollIntoView({behavior:'smooth',block:'start'})})}catch(e){if(document.contains(target))target.innerHTML='<p class="data-note">Network statistics are temporarily unavailable.</p>'}}

function reviewedDetail(p){document.querySelector('#detail').innerHTML=`<div class="detailhero">${logo(p)}<div><span class="eyebrow">REVIEWED COMMUNITY LISTING</span><h1 style="margin-top:10px">${escape(p.name)}</h1><p>${escape(p.description)}</p></div><a class="button small" href="${escape(p.website)}" target="_blank" rel="noopener">Open website ↗</a></div><div class="badges">${badges(p.networks)}<span class="badge">Approved · ${escape(p.approvedAt)}</span></div><section class="panel"><h2>Approved scope</h2><p>${escape(p.approvalScope)}</p><p><a class="hs-link" href="${escape(p.reference)}" target="_blank" rel="noopener">Public review and approval ↗</a></p><p class="muted">Reviewed by X402blockchains. Directory approval is not a security audit or an uptime guarantee.</p></section><section class="panel"><h2>Activity coverage</h2><p>${p.sampleOnly&&!p.activityConnected?'This local preview contains the independently checked payment examples. Complete recipient history is not connected yet.':'The live index below covers the approved payment recipients and networks. It does not measure off-chain requests, web visitors or activity on other wallets, assets and networks.'}</p><p class="muted">The reviewed payment examples are separate evidence, not platform-wide totals.</p></section><section class="panel" id="reviewed-onchain"><h2>On-chain activity</h2><p class="muted">Loading indexed recipient activity…</p></section><section class="panel"><h2>Verified payment examples</h2><div class="tablewrap"><table><thead><tr><th>Network</th><th>Payment</th><th>Evidence</th><th>Block / slot</th></tr></thead><tbody>${p.evidence.map(e=>`<tr><td>${escape(e.network)}</td><td>${escape(e.amountUSDC)} USDC</td><td><a href="${escape(e.url)}" target="_blank" rel="noopener">${short(e.transaction)} ↗</a><br><small>${escape(e.kind)} · Success</small></td><td>${num(e.position)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Checked on-chain on ${escape(p.approvedAt)}. Payment success and recipient were verified independently. Delivery captures remain evidence supplied by the operator.</p></section><section class="panel"><h2>Documentation & support</h2><p><a class="hs-link" href="${escape(p.documentation)}" target="_blank" rel="noopener">Integration documentation ↗</a></p><p><a class="hs-link" href="${escape(p.repository)}" target="_blank" rel="noopener">Official project / repository ↗</a></p><p><a class="hs-link" href="${escape(p.support)}" target="_blank" rel="noopener">Project support ↗</a></p><h3>Example paid resource</h3>${p.services.map(s=>`<p><code>${escape(s.method)} ${escape(s.url)}</code></p>`).join('')}<p class="muted">Use the latest payment challenge and official documentation for current prices. No payment is initiated by viewing this profile.</p></section>`;wire();loadReviewedActivity(p);}
async function loadReviewedActivity(p){if(p.sampleOnly&&!p.activityConnected){const el=document.querySelector('#reviewed-onchain');if(el)el.innerHTML=`<h2>Payment evidence verified</h2><p>${p.evidence.length} successful operator test payment example${p.evidence.length===1?'':'s'} checked. These examples do not establish total transactions, customers or platform volume.</p><p class="muted">Full activity totals and charts are not connected in this local preview. A missing count does not mean zero usage. Verified transaction links and amounts are shown below.</p>`;return;}try{const key=p.activityKey||({'tanod.dev':'tanod','horizonpulse.dev':'horizon','vextorium.com':'vextorium'}[p.id]);const r=await fetch((p.sampleOnly?'/new-listings/community-activity.php?project=':'/new-listings/activity.php?project=')+key,{cache:'no-store'});if(!r.ok)return;const d=await r.json();const localTime=dateTime;const target=document.querySelector('#reviewed-onchain');if(!target)return;target.innerHTML=`<h2>${p.activityShared?'Shared recipient wallet':'Recipient activity'} · last 30 days</h2><div class="stats"><div class="stat"><p>USDC RECEIPTS · INDEXED</p><strong>${num(d.transactions)}</strong></div><div class="stat"><p>SENDER WALLETS · INDEXED</p><strong>${num(d.wallets)}</strong><small>${d.walletCountPartial?'Some sender identities are unavailable':'Wallets, not individual users'}</small></div><div class="stat"><p>USDC VOLUME · INDEXED</p><strong>${d.volumeUSDC===null||d.volumeUSDC===undefined?'—':Number(d.volumeUSDC).toLocaleString(undefined,{maximumFractionDigits:6})}</strong><small>USDC received · same 30-day records</small></div></div><p class="muted">${d.partial?'Recent activity connected · older history in progress':'30-day recipient index'} · ${d.updatedAt?'Last checked '+localTime(d.updatedAt*1000):'Scheduled sync starting'}. ${d.status==='delayed'?'RPC update delayed; retained evidence is shown.':''}</p><p class="muted">${Object.entries(d.perNetwork||{}).map(([n,c])=>escape(n)+': '+num(c)+' receipts').join(' · ')}.</p>${d.solanaAccountTransactions&&d.partial?`<p class="muted">Older Solana history is still being verified. Totals include verified receipts only.</p>`:''}${d.rows?.[0]?.timestamp?`<p class="muted">Most recent USDC transfer: ${escape(localTime(d.rows[0].timestamp*1000))}.</p>`:''}${d.asOf?`<p class="muted">Chain records checked through ${escape(localTime(d.asOf*1000))}. A recent check does not imply a new payment.</p>`:''}${chart(d.history)}<p class="muted">${escape(d.coverage)}</p><div class="tablewrap"><table><thead><tr><th>Transaction</th><th>Network</th><th>Sender</th><th>Date</th></tr></thead><tbody>${d.rows.map(x=>`<tr><td><a href="${x.network==='Base'?'https://basescan.org/tx/':'https://solscan.io/tx/'}${escape(x.hash)}" target="_blank" rel="noopener">${short(x.hash)} ↗</a></td><td>${escape(x.network)}</td><td>${short(x.payer)}</td><td>${escape(localTime(x.timestamp*1000))}</td></tr>`).join('')}</tbody></table></div>`;}catch{const t=document.querySelector('#reviewed-onchain');if(t)t.innerHTML='<h2>On-chain activity</h2><p class="muted">Activity is temporarily unavailable. The independently reviewed payment examples remain below.</p>';}}
// Refresh data while preserving the selected project, network, period and page.
function refreshVisibleActivity(){
 if(document.hidden)return;
 snapshotPromise=undefined;detailPromises.clear();
 const params=new URLSearchParams(location.search);
 if(params.has('project')){const y=scrollY;Promise.resolve(refreshDetail?.()).then(()=>scrollTo(0,y));}
 else if(!params.has('view')){loadProjects();loadNetworks();}
}
setInterval(refreshVisibleActivity,60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshVisibleActivity()});
